gpr(){return"\uac8c\uc784 \uc124\uc815\uc740 \uacc4\uc815, \ud50c\ub808\uc774\uc5b4 \uc2e0\uc6d0, \uc544\ubc14\ud0c0, \uc5b8\uc5b4, \uc74c\uc545, \uc0ac\uc6b4\ub4dc \ubc0f \uc9c4\ud589 \uc0c1\ud669\uc744 \uad00\ub9ac\ud569\ub2c8\ub2e4."},
